<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Application\Policy\Allow\Delete;

use Override;
use Throwable;

use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Delete\ThemeDeleteAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedDeleteAllow
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(private readonly Context $context)
  {
  }
  public function __invoke(ThemeDeleteAllowDecision $proposal): ThemeDeleteAllowDecision
  {
    $this->logDebug("Check IsAuthenticatedDeleteAllow Theme");
    $span = $this->startSpan("Check IsAuthenticatedDeleteAllow Theme");
    try {
      $userContext = $this->context->getIdentity();
      if( $proposal->isAllowed()) {
        if( ! !$userContext->anonymous ) {
          $proposal->deny('Disabled if not IsAuthenticatedDelete');
        }      }
      return $proposal;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
